/**
 * Finds the player's `tool_export.json` on this machine, so a caller does not have to know where
 * the game put it.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    TOWER_TOOL_EXPORT_ENV, findToolExport
 * depends    src/node/types, src/save/access/path
 * used by    src/node/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import * as nodeFs from 'node:fs'
import * as os from 'node:os'
import * as path from 'node:path'

import {
  TOWER_ANDROID_PACKAGE,
  TOWER_MACOS_CONTAINERS_RELATIVE,
  TOWER_MACOS_TOOL_EXPORT_RELATIVE,
  TOWER_TOOL_EXPORT_FILENAME,
} from '../save/access/path'
import type { FindToolExportFs, FindToolExportOptions, FoundToolExport } from './types'

/** Environment variable naming the export outright; checked before any search. */
export const TOWER_TOOL_EXPORT_ENV = 'TOWER_TOOL_EXPORT'

/** The container metadata file macOS writes, which holds the app's bundle id. */
const MACOS_CONTAINER_METADATA = '.com.apple.containermanagerd.metadata.plist'

function fileModifiedAt(fs: FindToolExportFs, file: string): number | null {
  try {
    const stats = fs.statSync(file)
    return stats.isFile() ? stats.mtimeMs : null
  }
  catch {
    return null
  }
}

/** True when a container's metadata names the game. A container without readable metadata is not. */
function isTowerContainer(fs: FindToolExportFs, container: string): boolean {
  try {
    // The plist is binary, and the bundle id sits in it as plain ASCII.
    return Buffer.from(fs.readFileSync(path.join(container, MACOS_CONTAINER_METADATA))).includes(TOWER_ANDROID_PACKAGE)
  }
  catch {
    return false
  }
}

/**
 * Look for `tool_export.json` where the game writes it.
 *
 * Order: the `TOWER_TOOL_EXPORT` environment variable, then on macOS every
 * `~/Library/Containers/<id>/Data/Documents/tool_export.json`. The container is named after a
 * per-install UUID, so all of them are scanned; one whose metadata names the game wins over one
 * that merely holds a file of that name, and among equals the most recently written wins.
 *
 * Android and Windows are not searched: an Android export lives on the device, not on this disk.
 * Never throws; a folder that cannot be read counts as holding nothing.
 */
export function findToolExport(options: FindToolExportOptions = {}): FoundToolExport {
  const fs = options.fs ?? (nodeFs as unknown as FindToolExportFs)
  const env = options.env ?? process.env
  const platform = options.platform ?? process.platform
  const searched: string[] = []

  const fromEnv = env[TOWER_TOOL_EXPORT_ENV]?.trim()
  if (fromEnv) {
    searched.push(`${TOWER_TOOL_EXPORT_ENV}=${fromEnv}`)
    if (fileModifiedAt(fs, fromEnv) !== null) return { path: fromEnv, source: 'env', searched }
  }

  if (platform === 'darwin') {
    const containers = path.join(options.home ?? os.homedir(), TOWER_MACOS_CONTAINERS_RELATIVE)
    searched.push(path.join(containers, '*', TOWER_MACOS_TOOL_EXPORT_RELATIVE))
    let names: string[] = []
    try {
      names = fs.readdirSync(containers)
    }
    catch {
      names = []
    }
    const found = names
      .map((name) => {
        const container = path.join(containers, name)
        const file = path.join(container, TOWER_MACOS_TOOL_EXPORT_RELATIVE)
        const modifiedAt = fileModifiedAt(fs, file)
        return modifiedAt === null ? null : { file, modifiedAt, isTower: isTowerContainer(fs, container) }
      })
      .filter((entry): entry is { file: string, modifiedAt: number, isTower: boolean } => entry !== null)
      .sort((a, b) => Number(b.isTower) - Number(a.isTower) || b.modifiedAt - a.modifiedAt)
    if (found[0]) return { path: found[0].file, source: 'macos-container', searched }
  }

  if (searched.length === 0) {
    searched.push(`nowhere on ${platform}: set ${TOWER_TOOL_EXPORT_ENV} to the ${TOWER_TOOL_EXPORT_FILENAME} path`)
  }
  return { path: null, source: null, searched }
}
